// Approved is not paid yet: ship only after PAYMENT.CAPTURE.COMPLETED.
void approvedOrderId(event)
return { status: 200, body: { handled: event.event_type } }

const shipped = one(db, 'SELECT 1 AS found FROM shipments WHERE paypal_order_id = ?', orderId)
const held = one(db, 'SELECT 1 AS found FROM orders WHERE paypal_order_id = ? AND on_hold = 1', orderId)
const disputed = one(db, "SELECT 1 AS found FROM captures WHERE paypal_capture_id = ? AND status = 'DISPUTED'", captureId)
if (!shipped && !held && !disputed) shipOrder(db, orderId, event.event_type)

const disputedId = disputedCaptureId(event)
const capture = one(db, 'SELECT paypal_order_id FROM captures WHERE paypal_capture_id = ?', disputedId)
if (capture) run(db, 'UPDATE orders SET on_hold = 1 WHERE paypal_order_id = ?', String(capture.paypal_order_id))
run(db, "INSERT INTO captures (paypal_capture_id, paypal_order_id, amount, status) VALUES (?, '', '0.00', 'DISPUTED') ON CONFLICT(paypal_capture_id) DO UPDATE SET status = 'DISPUTED'", disputedId)

export function startReconcile(db: Db, port: PaypalPort): void {
  let busy = false
  const timer = setInterval(async () => {
    if (busy) return
    busy = true
    try {
      const orders = all(db, "SELECT DISTINCT paypal_order_id FROM captures WHERE paypal_order_id <> ''")
      for (const row of orders) {
        const orderId = String(row.paypal_order_id)
        const ledger = await port.getOrder(orderId)
        for (const refund of ledger.refunds) {
          run(db, 'INSERT OR IGNORE INTO refunds (paypal_refund_id, paypal_order_id, amount) VALUES (?, ?, ?)', refund.id, orderId, refund.amount)
        }
      }
    } catch {
      // try again on the next tick
    } finally {
      busy = false
    }
  }, 1500)
  timer.unref()
}
